func (s *Storage) AckEvent(ctx context.Context, id, channelID string) (bool, error) {
	var res sql.Result
	var err error
	if channelID != "" {
		res, err = s.writeDB.ExecContext(ctx, `
			UPDATE events
			SET status = 'acked', acked_at = CURRENT_TIMESTAMP
			WHERE id = ? AND channel_id = ?
		`, id, channelID)
	} else {
		res, err = s.writeDB.ExecContext(ctx, `
			UPDATE events
			SET status = 'acked', acked_at = CURRENT_TIMESTAMP
			WHERE id = ?
		`, id)
	}
	if err != nil {
		return false, err
	}

	rows, err := res.RowsAffected()
	if err != nil {
		return false, err
	}
	return rows > 0, nil
}

