func (s *Storage) GetStats(ctx context.Context) (*StorageStats, error) {
	stats := &StorageStats{}

	rows, err := s.readDB.QueryContext(ctx, "SELECT status, COUNT(*) FROM events GROUP BY status")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var status string
		var count int64
		if err := rows.Scan(&status, &count); err != nil {
			return nil, err
		}
		switch status {
		case "pending":
			stats.PendingEvents = count
		case "acked":
			stats.AckedEvents = count
		}
		stats.TotalEvents += count
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	if fi, err := os.Stat(s.dbPath); err == nil {
		stats.DBSizeBytes = fi.Size()
	}
	if fi, err := os.Stat(s.dbPath + "-wal"); err == nil {
		stats.WALSizeBytes = fi.Size()
	}

	return stats, nil
}

func (s *Storage) PruneEvents(ctx context.Context, ackedCutoff, unackedCutoff time.Time) (int64, error) {
	ackedStr := ackedCutoff.UTC().Format("2006-01-02 15:04:05")
	unackedStr := unackedCutoff.UTC().Format("2006-01-02 15:04:05")

	res, err := s.writeDB.ExecContext(ctx, `
		DELETE FROM events
		WHERE (status = 'acked' AND (acked_at <= ? OR created_at <= ?))
		   OR (created_at <= ?)
	`, ackedStr, ackedStr, unackedStr)
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

func (s *Storage) StartHousekeeper(ctx context.Context, interval, ackedRetention, unackedRetention time.Duration) {
	go func() {
		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				now := time.Now()
				ackedCutoff := now.Add(-ackedRetention)
				unackedCutoff := now.Add(-unackedRetention)

				pruneCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
				deleted, err := s.PruneEvents(pruneCtx, ackedCutoff, unackedCutoff)
				cancel()

				if err != nil {
					log.Printf("[WebSG Housekeeper] Error pruning events: %v", err)
				} else if deleted > 0 {
					log.Printf("[WebSG Housekeeper] Pruned %d expired event(s)", deleted)
				}
			}
		}
	}()
}

func (s *Storage) Close() error {
	close(s.writeChan)
	s.wg.Wait()
	if s.insertStmt != nil {
		s.insertStmt.Close()
	}
	var writeErr, readErr error
	if s.writeDB != nil {
		writeErr = s.writeDB.Close()
	}
	if s.readDB != nil {
		readErr = s.readDB.Close()
	}
	if writeErr != nil {
		return writeErr
	}
	return readErr
}

func (s *Storage) Ping(ctx context.Context) error {
	if err := s.writeDB.PingContext(ctx); err != nil {
		return err
	}
	return s.readDB.PingContext(ctx)
}
